        List<OrderItem> items = Arrays.asList(
                new OrderItem("Widget", 25.00, 2),
                new OrderItem("Gadget", 30.00, 2),
                new OrderItem("Tool", 15.00, 1)
        );

        Order order = new Order(items);
        System.out.println(order.generateReceipt());
